# POST /api/sheets/{sheetId}/claims/{claimId}/remind — remind an OPEN or PENDING claim on the sheet's
# today; refused (409) for any other status, or when it was already reminded on that day.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: remind
remind:
  class: net.officefloor.hq.app.claim.RemindClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveReminder
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/claims/{claimId}/proofs — raise a claim's proofs count by one; refused (409)
# for a SETTLED or VOID claim, (423) for a claim due by a day in a closed period.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.claim.AddProof
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveProofs
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimProofAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Reminds an OPEN or PENDING claim on the sheet's today. Refused for a claim in any other status, and
 *  for one already reminded on the sheet's today. */
public class RemindClaim {
    public void remind(@Val Claim claim, SheetRepository sheets) throws ClaimStatusException {
        if (!ClaimStatus.isOpen(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be reminded");
        }
        String today = sheets.today(claim.getSheetId()).toString();
        if (today.equals(claim.getReminded())) {
            throw new ClaimStatusException("The claim was already reminded on " + today);
        }
        claim.setReminded(today);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveReminder {
    public void save(@Val Claim claim, ClaimRepository claims) {
        claims.updateReminded(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: a reminder that went through. */
public class RecordClaimReminded {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        audit.record(RecordClaimStatus.line("REMIND", by, claim, people));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/** Raises a claim's proofs count by one. Refused for a claim due by a day in a closed period, and for a
 *  SETTLED or VOID claim. */
public class AddProof {
    public void add(@Val Claim claim, PeriodRepository periods)
            throws ClaimStatusException, PeriodClosedException {
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        if (ClaimStatus.SETTLED.name().equals(claim.getStatus()) || ClaimStatus.VOID.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot gain a proof");
        }
