1	import { useEffect, useRef, useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import { HttpError } from '../../api/http';
4	import { useSubmitOnce } from '../../forms/useSubmitOnce';
5	import { listPeriods, periodOf, periodsKey } from '../periods/api';
6	import { claimDue, showDue, type GradeOn, type Late, type Rate } from '../rates/api';
7	import { useNoteThreshold, useProofThreshold, type DatedOn } from '../settings/api';
8	import { addClaim, addProof, claimsKey, listVoidReasons, voidReasonsKey, deferClaim, redateClaim, remindClaim, dueBy, isOverdue, lockClaim, moveClaim, reassignClaim, showTags, splitClaim, unlockClaim, updateClaim, type Claim, type ClaimAction, type ClaimInput } from './api';
9	
10	const EMPTY: ClaimInput = { amount: '', date: '', note: '', corrects: '', ref: '', tags: '' };
11	
12	const LABELS: Record<ClaimAction, string> = { open: 'Open', settle: 'Settle', void: 'Void', approve: 'Approve', reject: 'Reject', resettle: 'Re-settle' };
13	const DONE: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided', approve: 'approved', reject: 'rejected', resettle: 're-settled' };
14	
15	/** A person's claims: a form that adds a claim or edits one, and the claims newest first, each
16	 *  with its status, its due (fixed when settled, else at the rate in force on the claim's date of the
17	 *  person's grade in force then (`gradeOn`), or bound by the person's last statement; none when
18	 *  there is no such rate; an overdue one gains its late charge on top, see `charges`; then at least the sheet's `floor`), its due-by (fixed when it was added) and whether it is
19	 *  overdue (OPEN and due-by before the sheet's `today`), whether
20	 *  it is stated,
21	 *  the period its due-by falls in (none when no period contains it), its status log (oldest first), who opened it, and buttons that
22	 *  change its status (the user who opened a claim cannot settle it; a clerk settling one whose due is
23	 *  above the sheet's clerk limit makes it PENDING, which a steward other than its opener approves,
24	 *  or any steward rejects with a reason typed beside it), a checkbox that selects it for a bulk action, and for a correction (a negative amount, no floor and no late
25	 *  charge) the number of the SETTLED claim it corrects. Only a DRAFT can be edited:
26	 *  editing any other claim, or one due by a day in a closed period, is refused with an error on the claim. Opening a
27	 *  claim's editor locks it for other users until it is saved or cancelled or the sheet's today changes:
28	 *  another user's edit button on it is refused likewise, and the editor of a claim the user holds is
29	 *  open again when the sheet is re-loaded. A role the permission matrix allows (by default a steward) can move a DRAFT, OPEN or
30	 *  PENDING claim to another person picked beside it (any other refused with an error on the claim), and
31	 *  re-settle a SETTLED one (anyone else, any other status or a claim in a closed period refused likewise).
32	 *  An OPEN or PENDING claim can be reminded with a button beside it, once per sheet's today (a second reminder
33	 *  that day, or any other claim, refused with an error on the claim); the last day it was reminded is shown.
34	 *  An OPEN claim can be deferred until a date typed beside it, after the sheet's today (any other claim, date,
35	 *  or a claim in a closed period refused with an error on the claim); whether it is deferred, and until when, is shown.
36	 *  Its proofs count is shown and raised by one with a button beside it (a SETTLED or VOID claim, or one in a
37	 *  closed period, refused with an error on the claim); one with no proofs whose due is above the sheet's proof
38	 *  threshold in force on its date cannot be settled or approved.
39	 *  A steward can re-date an OPEN or PENDING claim to a date typed beside it: its due-by and any bound figure
40	 *  stay, and so do its period and number (anyone else, any other status, a date after its person's retirement,
41	 *  or a claim in a closed period refused with an error on the claim).
42	 *  An OPEN claim can be split by an amount typed beside it (more than 0.00, less than its own): it keeps the
43	 *  rest and is unbound, and a new OPEN claim of that amount, opened by the user, shows its number as split-from
44	 *  (a PENDING, deferred or settled claim, one in a closed period, or a role that may not open a claim refused
45	 *  with an error on the claim).
46	 *  A DRAFT's amount can be changed in its row, by an amount typed beside its edit button: saved as the
47	 *  claim form saves it (its date, note and corrected claim kept), refused likewise with an error on the claim. */
48	export function PersonClaims({ sheetId, user, personId, claims, gradeOn, rates, floor, today, charges, selected, onSelect, people }: {
49	  sheetId: string; user: string; personId: number; claims: Claim[]; gradeOn: GradeOn; rates: Rate[] | undefined;
50	  floor: DatedOn; today: string; charges: Late;
51	  /** The claims selected for a bulk action, and how one is selected or unselected. */
52	  selected: ReadonlySet<number>; onSelect: (id: number, on: boolean) => void;
53	  /** Everyone on the sheet, the people a claim can be moved to (all but `personId`). */
54	  people: Array<{ id: number; name: string }>;
55	}) {
56	  const queryClient = useQueryClient();
57	  const periods = useQuery({ queryKey: periodsKey(sheetId), queryFn: () => listPeriods(sheetId) });
58	  const [form, setForm] = useState<ClaimInput>(EMPTY);
59	  const [editing, setEditing] = useState<number | null>(null);
60	  // The claim whose edit was refused (not a DRAFT, in a closed period, or locked by another user), and
61	  // why; cleared by the next action on any claim here.
62	  const [editRefused, setEditRefused] = useState<{ id: number; message: string } | null>(null);
63	  // The rejection reason typed for each claim.
64	  const [reasons, setReasons] = useState<Record<number, string>>({});
65	  // The void reason chosen for each claim (blank: none), from the sheet's list.
66	  const [voidReasons, setVoidReasons] = useState<Record<number, string>>({});
67	  const voidReasonList = useQuery({ queryKey: voidReasonsKey(sheetId), queryFn: () => listVoidReasons(sheetId) });
68	
69	  const save = useMutation({
70	    mutationFn: (v: { id: number | null; input: ClaimInput }) =>
71	      v.id === null ? addClaim(sheetId, user, personId, v.input) : updateClaim(sheetId, user, v.id, v.input),
72	    onSuccess: () => {
73	      setForm(EMPTY);
74	      setEditing(null);
75	      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
76	    },
77	  });
78	
79	  // Opening a claim's editor takes its lock; a refusal leaves the editor open (a save is refused too)
80	  // with the error on the claim, until it is cancelled.
81	  const locking = useMutation({
82	    mutationFn: (id: number) => lockClaim(sheetId, user, id),
83	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
84	  });
85	  const unlocking = useMutation({
86	    mutationFn: (id: number) => unlockClaim(sheetId, user, id),
87	    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
88	  });
89	
90	  // The claim of this person whose lock the user holds: its editor is open, also after a re-load,
91	  // and closes when the lock goes (the sheet's today changed).
92	  const held = claims.find((c) => c.lockedBy === user && c.status === 'DRAFT');
93	  const heldWas = useRef<number | null>(null);
94	  useEffect(() => {
95	    const was = heldWas.current;
96	    heldWas.current = held?.id ?? null;
97	    if (held && editing === null) {
98	      setForm({ amount: held.amount, date: held.date, note: held.note, corrects: held.corrects ?? '', ref: held.ref ?? '', tags: showTags(held.tags) });
99	      setEditing(held.id);
100	    } else if (!held && was !== null && editing === was && !locking.isPending) {
101	      setForm(EMPTY);
102	      setEditing(null);
103	    }
104	    // eslint-disable-next-line react-hooks/exhaustive-deps
105	  }, [held?.id]);
106	
107	  const submitOnce = useSubmitOnce();
108	  const actOnce = useSubmitOnce();
109	
110	  // The claim whose last status change was refused; cleared by the next action on any claim here.
111	  const move = useMutation({
112	    mutationFn: (v: { id: number; action: ClaimAction }) =>
113	      moveClaim(sheetId, user, v.id, v.action, (v.action === 'void' ? voidReasons[v.id] : reasons[v.id]) ?? ''),
114	    onSuccess: (_, v) => {
115	      if (v.action === 'reject') setReasons((r) => ({ ...r, [v.id]: '' }));
116	      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
117	    },
118	  });
119	
120	  // The person picked for each claim to move to.
121	  const [targets, setTargets] = useState<Record<number, string>>({});
122	  const others = people.filter((p) => p.id !== personId);
123	
124	  // The date typed for each claim to defer it until.
125	  const [deferDates, setDeferDates] = useState<Record<number, string>>({});
126	
127	  const deferral = useMutation({
128	    mutationFn: (v: { id: number; until: string }) => deferClaim(sheetId, user, v.id, v.until),
129	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
130	  });
131	
132	  const defer = (id: number) => {
133	    const until = (deferDates[id] ?? '').trim();
134	    actOnce(() => {
135	      move.reset();
136	      reassign.reset();
137	      deferral.reset();
138	      reminder.reset();
139	      redating.reset();
140	      proof.reset();
141	      division.reset();
142	      inline.reset();
143	      setEditRefused(null);
144	      locking.reset();
145	      return deferral.mutateAsync({ id, until });
146	    });
147	  };
148	
149	  const reminder = useMutation({
150	    mutationFn: (id: number) => remindClaim(sheetId, user, id),
151	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
152	  });
153	
154	  const remind = (id: number) => {
155	    actOnce(() => {
156	      move.reset();
157	      reassign.reset();
158	      deferral.reset();
159	      reminder.reset();
160	      redating.reset();
161	      proof.reset();
162	      division.reset();
163	      inline.reset();
164	      setEditRefused(null);
165	      locking.reset();
166	      return reminder.mutateAsync(id);
167	    });
168	  };
169	
170	  // The new date typed for each claim to re-date it to.
171	  const [redates, setRedates] = useState<Record<number, string>>({});
172	
173	  const redating = useMutation({
174	    mutationFn: (v: { id: number; date: string }) => redateClaim(sheetId, user, v.id, v.date),
175	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
176	  });
177	
178	  const redate = (id: number) => {
179	    const date = (redates[id] ?? '').trim();
180	    actOnce(() => {
181	      move.reset();
182	      reassign.reset();
183	      deferral.reset();
184	      reminder.reset();
185	      redating.reset();
186	      proof.reset();
187	      division.reset();
188	      inline.reset();
189	      setEditRefused(null);
190	      locking.reset();
191	      return redating.mutateAsync({ id, date });
192	    });
193	  };
194	
195	  // The amount typed for each claim to split off it.
196	  const [splitAmounts, setSplitAmounts] = useState<Record<number, string>>({});
197	
198	  const division = useMutation({
199	    mutationFn: (v: { id: number; amount: string }) => splitClaim(sheetId, user, v.id, v.amount),
200	    onSuccess: (_, v) => {
201	      setSplitAmounts((a) => ({ ...a, [v.id]: '' }));
202	      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
203	    },
204	  });
205	
206	  const split = (id: number) => {
207	    const amount = (splitAmounts[id] ?? '').trim();
208	    actOnce(() => {
209	      move.reset();
210	      reassign.reset();
211	      deferral.reset();
212	      reminder.reset();
213	      redating.reset();
214	      proof.reset();
215	      division.reset();
216	      inline.reset();
217	      setEditRefused(null);
218	      locking.reset();
219	      return division.mutateAsync({ id, amount });
220	    });
221	  };
222	
223	  // The amount typed for each claim to change it to in its row.
224	  const [inlineAmounts, setInlineAmounts] = useState<Record<number, string>>({});
225	
226	  const inline = useMutation({
227	    mutationFn: (v: { id: number; input: ClaimInput }) => updateClaim(sheetId, user, v.id, v.input),
228	    onSuccess: (_, v) => {
229	      setInlineAmounts((a) => ({ ...a, [v.id]: '' }));
230	      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
231	    },
232	  });
233	
234	  const saveInline = (c: Claim) => {
235	    const input = { amount: (inlineAmounts[c.id] ?? '').trim(), date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '', tags: showTags(c.tags) };
236	    actOnce(() => {
237	      move.reset();
238	      reassign.reset();
239	      deferral.reset();
240	      reminder.reset();
241	      redating.reset();
242	      proof.reset();
243	      division.reset();
244	      inline.reset();
245	      setEditRefused(null);
246	      locking.reset();
247	      return inline.mutateAsync({ id: c.id, input });
248	    });
249	  };
250	
251	  const proof = useMutation({
252	    mutationFn: (id: number) => addProof(sheetId, user, id),
253	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
254	  });
255	
256	  const prove = (id: number) => {
257	    actOnce(() => {
258	      move.reset();
259	      reassign.reset();
260	      deferral.reset();
261	      reminder.reset();
262	      redating.reset();
263	      proof.reset();
264	      division.reset();
265	      inline.reset();
266	      setEditRefused(null);
267	      locking.reset();
268	      return proof.mutateAsync(id);
269	    });
270	  };
271	
272	  const proofThreshold = useProofThreshold(sheetId);
273	  // Whether a claim needs a proof before it is settled or approved: none yet, and its due above the threshold.
274	  const needsProof = (c: Claim) => {
275	    const threshold = proofThreshold(c.date);
276	    const due = claimDue(c, rates, gradeOn, floor, charges);
277	    return c.proofs === 0 && threshold !== null && due !== null && Number(due) > Number(threshold);
278	  };
279	
280	  const noteThreshold = useNoteThreshold(sheetId);
281	  // Whether a claim needs a note before it is opened: an empty one, and its due above the threshold.
282	  const needsNote = (c: Claim) => {
283	    const threshold = noteThreshold(c.date);
284	    const due = claimDue(c, rates, gradeOn, floor, charges);
285	    return (c.note ?? '').trim() === '' && threshold !== null && due !== null && Number(due) > Number(threshold);
