289	    mutationFn: (v: { id: number; to: number }) => reassignClaim(sheetId, user, v.id, v.to),
290	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
291	  });
292	
293	  const moveTo = (id: number) => {
294	    const to = Number(targets[id] ?? others[0]?.id ?? NaN);
295	    actOnce(() => {
296	      move.reset();
297	      reassign.reset();
298	      deferral.reset();
299	      reminder.reset();
300	      redating.reset();
301	      proof.reset();
302	      division.reset();
303	      inline.reset();
304	      setEditRefused(null);
305	      locking.reset();
306	      return reassign.mutateAsync({ id, to });
307	    });
308	  };
309	
310	  const act = (id: number, action: ClaimAction) => {
311	    actOnce(() => {
312	      move.reset();
313	      reassign.reset();
314	      deferral.reset();
315	      reminder.reset();
316	      redating.reset();
