326	  const change = (patch: Partial<ClaimInput>) => {
327	    setForm((f) => ({ ...f, ...patch }));
328	    save.reset();
329	  };
330	
331	  const open = (c: Claim) => {
332	    move.reset();
333	    reassign.reset();
334	    deferral.reset();
335	    reminder.reset();
336	    redating.reset();
