347	      return;
348	    }
349	    if (c.lockedBy !== null && c.lockedBy !== undefined && c.lockedBy !== user) {
350	      setEditRefused({ id: c.id, message: `${c.lockedBy} is editing this claim; it cannot be edited until they save or cancel.` });
351	      return;
352	    }
353	    setEditRefused(null);
354	    setForm({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '', tags: showTags(c.tags) });
355	    setEditing(c.id);
356	    save.reset();
357	    locking.mutate(c.id);
358	  };
359	
360	  const cancel = () => {
361	    const id = editing;
362	    setForm(EMPTY);
363	    setEditing(null);
364	    save.reset();
365	    locking.reset();
366	    setEditRefused(null);
367	    if (id !== null) unlocking.mutate(id);
368	  };
369	
370	  return (
371	    <div>
372	      <form
373	        onSubmit={(e) => {
374	          e.preventDefault();
375	          const v = { id: editing, input: form };
376	          submitOnce(() => {
377	            save.reset();
378	            return save.mutateAsync(v);
379	          });
380	        }}
381	      >
382	        <input data-testid="claim-form-amount" placeholder="Amount" value={form.amount}
383	          onChange={(e) => change({ amount: e.target.value })} />{' '}
384	        <input type="date" data-testid="claim-form-date" value={form.date}
385	          onChange={(e) => change({ date: e.target.value })} />{' '}
386	        <input data-testid="claim-form-note" placeholder="Note" value={form.note}
387	          onChange={(e) => change({ note: e.target.value })} />{' '}
388	        <input data-testid="claim-form-corrects" placeholder="Corrects no." value={form.corrects}
389	          onChange={(e) => change({ corrects: e.target.value })} />{' '}
390	        <input data-testid="claim-form-ref" placeholder="Reference" value={form.ref}
391	          onChange={(e) => change({ ref: e.target.value })} />{' '}
392	        <input data-testid="claim-form-tags" placeholder="Tags, comma separated" value={form.tags}
393	          onChange={(e) => change({ tags: e.target.value })} />{' '}
394	        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending || locking.isPending}>
395	          {editing === null ? 'Add claim' : 'Save claim'}
396	        </button>
397	        {save.isError && (
398	          <span data-testid="claim-form-error">{save.error instanceof HttpError && save.error.status === 423
399	            ? 'A claim due by a day inside a closed period cannot be added or edited.'
400	            : save.error instanceof HttpError && save.error.status === 409
401	            ? 'Only a DRAFT claim can be edited.'
402	            : save.error instanceof HttpError && save.error.status === 412
403	            ? 'Another user is editing this claim; it cannot be saved until they save or cancel.'
404	            : save.error instanceof HttpError && save.error.status === 403
405	            ? 'Your role may not change anything on this sheet.'
406	            : 'A claim needs an amount with up to two decimals; a negative one (a correction) must name, by number, a SETTLED claim of this person; a reference cannot be one already used on the sheet.'}</span>
407	        )}
408	      </form>
409	      <table>
410	        <tbody>
411	          {claims.map((c) => (
412	            <tr key={c.id} data-testid={`claim-row-${c.id}`}>
413	              <td>
414	                <input type="checkbox" data-testid="claim-select" checked={selected.has(c.id)}
415	                  onChange={(e) => onSelect(c.id, e.target.checked)} />
416	              </td>
417	              <td data-testid="claim-number">{c.number ?? ''}</td>
418	              <td data-testid="claim-amount">{Number(c.amount).toFixed(2)}</td>
419	              <td data-testid="claim-date">{c.date}</td>
420	              <td data-testid="claim-note">{c.note}</td>
421	              <td data-testid="claim-corrects">{c.corrects ?? ''}</td>
422	              <td data-testid="claim-ref">{c.ref ?? ''}</td>
423	              <td data-testid="claim-tags">{showTags(c.tags)}</td>
424	              <td data-testid="claim-due">{showDue(claimDue(c, rates, gradeOn, floor, charges))}</td>
425	              <td>
426	                Due by <span data-testid="claim-due-by">{dueBy(c)}</span>{' '}
427	                overdue <span data-testid="claim-overdue">{isOverdue(c, today, charges.lateFrom(c)) ? 'yes' : 'no'}</span>
428	              </td>
429	              <td data-testid="claim-status">{c.status}</td>
430	              <td data-testid="claim-opened-by">{c.openedBy ?? ''}</td>
431	              <td>
432	                Stated <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>
433	              </td>
434	              <td>
435	                Deferred <span data-testid="claim-deferred">{c.deferred ? 'yes' : 'no'}</span>{' '}
436	                until <span data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</span>
437	              </td>
438	              <td>
439	                Reminded <span data-testid="claim-reminded">{c.reminded ?? ''}</span>{' '}
440	                <button type="button" data-testid="claim-remind" disabled={reminder.isPending}
441	                  onClick={() => remind(c.id)}>
442	                  Remind
443	                </button>
444	              </td>
445	              <td>
446	                Proofs <span data-testid="claim-proofs">{c.proofs ?? 0}</span>{' '}
447	                <button type="button" data-testid="claim-proof" disabled={proof.isPending}
448	                  onClick={() => prove(c.id)}>
449	                  Add proof
450	                </button>
451	              </td>
452	              <td>
453	                Late entry <span data-testid="claim-late-entry">{c.lateEntry ? 'yes' : 'no'}</span>{' '}
454	                Split from <span data-testid="claim-split-from">{c.splitFrom ?? ''}</span>{' '}
455	                <input data-testid="claim-split-amount" placeholder="Split amount" value={splitAmounts[c.id] ?? ''}
456	                  onChange={(e) => {
457	                    setSplitAmounts((a) => ({ ...a, [c.id]: e.target.value }));
458	                    if (division.variables?.id === c.id) division.reset();
459	                  }} />{' '}
460	                <button type="button" data-testid="claim-split" disabled={division.isPending}
461	                  onClick={() => split(c.id)}>
462	                  Split
463	                </button>
464	              </td>
465	              <td data-testid="claim-period">{periodOf(periods.data, c.dueBy)?.name ?? ''}</td>
466	              <td>
467	                {(c.log ?? []).map((line, i) => <div key={i} data-testid="claim-log-line">{line}</div>)}
468	              </td>
469	              <td>
470	                {(['open', 'settle', 'void', 'approve', 'resettle'] as const).map((a) => (
471	                  <button key={a} type="button" data-testid={`claim-${a}`} disabled={move.isPending}
472	                    onClick={() => act(c.id, a)}>
473	                    {LABELS[a]}
474	                  </button>
475	                ))}{' '}
476	                <select data-testid="claim-void-reason" value={voidReasons[c.id] ?? ''}
477	                  onChange={(e) => {
478	                    setVoidReasons((r) => ({ ...r, [c.id]: e.target.value }));
479	                    if (move.variables?.id === c.id) move.reset();
480	                  }}>
481	                  <option value="">No void reason</option>
482	                  {(voidReasonList.data ?? []).map((r) => <option key={r.reason} value={r.reason}>{r.reason}</option>)}
483	                </select>{' '}
484	                <input data-testid="claim-reject-reason" placeholder="Reason" value={reasons[c.id] ?? ''}
485	                  onChange={(e) => {
486	                    setReasons((r) => ({ ...r, [c.id]: e.target.value }));
487	                    if (move.variables?.id === c.id) move.reset();
488	                  }} />{' '}
489	                <button type="button" data-testid="claim-reject" disabled={move.isPending}
490	                  onClick={() => act(c.id, 'reject')}>
491	                  {LABELS.reject}
492	                </button>{' '}
493	                <input type="date" data-testid="claim-defer-date" value={deferDates[c.id] ?? ''}
494	                  onChange={(e) => {
495	                    setDeferDates((d) => ({ ...d, [c.id]: e.target.value }));
496	                    if (deferral.variables?.id === c.id) deferral.reset();
497	                  }} />{' '}
498	                <button type="button" data-testid="claim-defer" disabled={deferral.isPending}
499	                  onClick={() => defer(c.id)}>
500	                  Defer
501	                </button>{' '}
502	                <input type="date" data-testid="claim-date-new" value={redates[c.id] ?? ''}
503	                  onChange={(e) => {
504	                    setRedates((d) => ({ ...d, [c.id]: e.target.value }));
505	                    if (redating.variables?.id === c.id) redating.reset();
506	                  }} />{' '}
507	                <button type="button" data-testid="claim-redate" disabled={redating.isPending}
508	                  onClick={() => redate(c.id)}>
509	                  Re-date
510	                </button>{' '}
511	                <select data-testid="claim-reassign-to" value={targets[c.id] ?? String(others[0]?.id ?? '')}
512	                  onChange={(e) => {
513	                    setTargets((t) => ({ ...t, [c.id]: e.target.value }));
514	                    if (reassign.variables?.id === c.id) reassign.reset();
515	                  }}>
516	                  {others.map((p) => <option key={p.id} value={String(p.id)}>{p.name}</option>)}
517	                </select>{' '}
518	                <button type="button" data-testid="claim-reassign" disabled={reassign.isPending || others.length === 0}
519	                  onClick={() => moveTo(c.id)}>
520	                  Reassign
521	                </button>{' '}
522	                <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
523	                  Edit
524	                </button>{' '}
525	                <input data-testid="claim-inline-amount" placeholder="Amount" value={inlineAmounts[c.id] ?? ''}
526	                  onChange={(e) => {
527	                    setInlineAmounts((a) => ({ ...a, [c.id]: e.target.value }));
528	                    if (inline.variables?.id === c.id) inline.reset();
529	                  }} />{' '}
530	                <button type="button" data-testid="claim-inline-save" disabled={inline.isPending}
531	                  onClick={() => saveInline(c)}>
532	                  Save amount
533	                </button>
534	                {editing === c.id && (
535	                  <button type="button" data-testid="claim-cancel" onClick={cancel}>
536	                    Cancel
537	                  </button>
538	                )}
539	                {editRefused?.id === c.id && (
540	                  <span data-testid="claim-error">{editRefused.message}</span>
541	                )}
542	                {locking.isError && locking.variables === c.id && (
543	                  <span data-testid="claim-error">{locking.error instanceof HttpError && locking.error.status === 412
544	                    ? 'Another user is editing this claim; it cannot be edited until they save or cancel.'
545	                    : locking.error instanceof HttpError && locking.error.status === 423
546	                    ? 'A claim due by a day inside a closed period cannot be edited.'
547	                    : locking.error instanceof HttpError && locking.error.status === 409
548	                    ? `A ${c.status} claim cannot be edited. To change it, void it and add a new one.`
549	                    : 'Your role may not edit a claim.'}</span>
550	                )}
551	                {move.isError && move.variables?.id === c.id && (
552	                  <span data-testid="claim-error">{move.error instanceof HttpError && move.error.status === 423
553	                    ? 'A claim due by a day inside a closed period cannot be changed.'
554	                    : move.error instanceof HttpError && move.error.status === 400 && move.variables.action === 'void'
555	                    ? 'A void needs a reason chosen from the void reasons.'
556	                    : move.error instanceof HttpError && move.error.status === 400
557	                    ? 'A rejection needs a reason.'
558	                    : (move.variables.action === 'settle' || move.variables.action === 'approve') && needsProof(c)
559	                    ? 'A claim whose due is above the proof threshold needs a proof first.'
560	                    : move.variables.action === 'open' && c.status === 'DRAFT' && needsNote(c)
561	                    ? 'A claim whose due is above the note threshold needs a note before it is opened.'
562	                    : c.deferred && move.variables.action === 'settle'
563	                    ? `A deferred claim cannot be settled until ${c.deferredUntil}.`
564	                    : c.status === 'OPEN' && move.variables.action === 'settle'
565	                    ? 'The user who opened a claim cannot settle it, nor can a role the permissions do not allow to settle.'
566	                    : c.status === 'PENDING' && move.variables.action === 'approve'
567	                    ? 'Only a steward who did not open a claim can approve it.'
568	                    : c.status === 'PENDING' && move.variables.action === 'reject'
569	                    ? 'Only a steward can reject a claim.'
570	                    : c.status === 'SETTLED' && move.variables.action === 'resettle'
571	                    ? 'Only a steward can re-settle a claim.'
572	                    : `A ${c.status} claim cannot be ${DONE[move.variables.action]}, or your role may not ${move.variables.action} a claim.`}</span>
573	                )}
574	                {deferral.isError && deferral.variables?.id === c.id && (
575	                  <span data-testid="claim-error">{deferral.error instanceof HttpError && deferral.error.status === 423
576	                    ? 'A claim due by a day inside a closed period cannot be deferred.'
577	                    : deferral.error instanceof HttpError && deferral.error.status === 400
578	                    ? 'A claim can only be deferred to a date after the sheet\'s today.'
579	                    : `A ${c.status} claim cannot be deferred.`}</span>
580	                )}
581	                {reminder.isError && reminder.variables === c.id && (
582	                  <span data-testid="claim-error">{reminder.error instanceof HttpError && reminder.error.status === 409
583	                    ? (c.status === 'OPEN' || c.status === 'PENDING'
584	                      ? `The claim was already reminded on ${c.reminded ?? today}.`
585	                      : `A ${c.status} claim cannot be reminded.`)
586	                    : 'Your role may not remind a claim.'}</span>
587	                )}
588	                {redating.isError && redating.variables?.id === c.id && (
589	                  <span data-testid="claim-error">{redating.error instanceof HttpError && redating.error.status === 423
590	                    ? 'A claim due by a day inside a closed period cannot be re-dated.'
591	                    : redating.error instanceof HttpError && redating.error.status === 400
592	                    ? 'A claim needs a date on or before its person\'s retirement.'
593	                    : c.status === 'OPEN' || c.status === 'PENDING'
594	                    ? 'Only a steward can re-date a claim.'
595	                    : `A ${c.status} claim cannot be re-dated.`}</span>
596	                )}
597	                {division.isError && division.variables?.id === c.id && (
598	                  <span data-testid="claim-error">{division.error instanceof HttpError && division.error.status === 423
599	                    ? 'A claim due by a day inside a closed period cannot be split.'
600	                    : division.error instanceof HttpError && division.error.status === 400
601	                    ? `A split needs an amount more than 0.00 and less than ${Number(c.amount).toFixed(2)}.`
602	                    : c.status === 'OPEN' && !c.deferred
603	                    ? 'Your role may not open a claim, so it cannot split one.'
604	                    : `A ${c.deferred ? 'deferred' : c.status} claim cannot be split.`}</span>
605	                )}
606	                {proof.isError && proof.variables === c.id && (
607	                  <span data-testid="claim-error">{proof.error instanceof HttpError && proof.error.status === 423
608	                    ? 'A claim due by a day inside a closed period cannot gain a proof.'
609	                    : `A ${c.status} claim cannot gain a proof.`}</span>
610	                )}
611	                {inline.isError && inline.variables?.id === c.id && (
612	                  <span data-testid="claim-error">{inline.error instanceof HttpError && inline.error.status === 423
613	                    ? 'A claim due by a day inside a closed period cannot be edited.'
614	                    : inline.error instanceof HttpError && inline.error.status === 409
615	                    ? `A ${c.status} claim cannot be edited. To change it, void it and add a new one.`
616	                    : inline.error instanceof HttpError && inline.error.status === 412
617	                    ? 'Another user is editing this claim; it cannot be saved until they save or cancel.'
618	                    : inline.error instanceof HttpError && inline.error.status === 403
619	                    ? 'Your role may not change anything on this sheet.'
620	                    : 'A claim needs an amount with up to two decimals; a negative one (a correction) must name, by number, a SETTLED claim of this person.'}</span>
621	                )}
622	                {reassign.isError && reassign.variables?.id === c.id && (
623	                  <span data-testid="claim-error">{reassign.error instanceof HttpError && reassign.error.status === 423
624	                    ? 'A claim due by a day inside a closed period cannot be reassigned.'
625	                    : c.status === 'SETTLED' || c.status === 'VOID'
626	                    ? `A ${c.status} claim cannot be reassigned.`
627	                    : 'Only a role the permissions allow can reassign a claim, and only to another person.'}</span>
628	                )}
629	              </td>
630	            </tr>
631	          ))}
632	        </tbody>
633	      </table>
634	    </div>
635	  );
636	}
